   470  size_t BgpUpdateMessageLayer::pathAttributesToByteArray(const std::vector<path_attribute>& pathAttributes, uint8_t* resultByteArr, size_t maxByteArrSize)
   471  {
   472          if (resultByteArr == nullptr || maxByteArrSize == 0)
   473          {
   474                  return 0;
   475          }
   476
   477          size_t dataLen = 0;
   478
   479          for (std::vector<path_attribute>::const_iterator iter = pathAttributes.begin(); iter != pathAttributes.end(); iter++)
   480          {
   481                  if (iter->length > 32)
   482                  {
   483                          PCPP_LOG_ERROR("Illegal path attribute length " << (int)iter->length);
   484                          break; // illegal value
   485                  }
   486
   487                  size_t curDataSize = 3*sizeof(uint8_t) + (size_t)iter->length;
   488
   489                  if (dataLen + curDataSize > maxByteArrSize)
   490                  {
   491                          break;
   492                  }
   493
   494                  resultByteArr[0] = iter->flags;
   495                  resultByteArr[1] = iter->type;
   496                  resultByteArr[2] = iter->length;
   497                  if (iter->length > 0)
   498                  {
   499                          memcpy(resultByteArr + 3*sizeof(uint8_t), iter->data, iter->length);
   500                  }
   501
   502                  dataLen += curDataSize;
   503                  resultByteArr += curDataSize;
   504          }
   505
   506          return dataLen;
