   510  {
   511          size_t headerLen = getHeaderLen();
   512          size_t minLen = sizeof(bgp_common_header) + sizeof(uint16_t);
   513          if (headerLen >= minLen)
   514          {
   515                  uint16_t res = be16toh(*(uint16_t*)(m_Data + sizeof(bgp_common_header)));
   516                  if ((size_t)res > headerLen - minLen)
